-- Increase the size of a VARCHAR column
ALTER TABLE production.products
ALTER COLUMN product_name VARCHAR(300);

-- Caution: this destroys data irreversibly
ALTER TABLE production.products
DROP COLUMN obsolete_notes;

-- Create a new schema
CREATE SCHEMA purchasing;

-- Create a table inside it
CREATE TABLE purchasing.vendors (
    vendor_id  INT IDENTITY PRIMARY KEY,
    vendor_name NVARCHAR(100) NOT NULL
);

-- Move a table from dbo to purchasing
ALTER SCHEMA purchasing
TRANSFER dbo.old_vendors;

-- Rename a table
sp_rename 'Sales.Orders', 'Sales.CompletedOrders';

-- Rename an index
sp_rename 'Sales.CompletedOrders.IX_CompletedOrders_Date',
           'IX_CompletedOrders_Date';

-- Drop a table if it exists
DROP TABLE IF EXISTS production.product_backup;

-- Drop a database
DROP DATABASE IF EXISTS temp_test;

-- Drop a view
DROP VIEW IF EXISTS sales.daily_sales;

-- Drop an index
DROP INDEX IF EXISTS IX_products_name ON production.products;

-- Create a synonym for a table in another database
CREATE SYNONYM suppliers
FOR test.purchasing.suppliers;

-- Use the synonym as if it were a real table
SELECT * FROM suppliers;
